          {/* 3. STAGE: ROUTE OVERVIEW */}
          {session.stage === 'routeOverview' && (
            <div>
              <h1 className="text-2xl font-bold text-[#1c3257] mb-4">Nuestra ruta de {lessonData.metadata.subject}</h1>
